package com.example.meetomxh.supabase;
import com.example.meetomxh.models.*;
import org.json.*;
import java.util.*;
public final class Dto {
 public static String nullable(JSONObject o,String key){return o==null||o.isNull(key)?null:o.optString(key,null);}
 public static String asset(String id){return id==null||id.isEmpty()?"":"asset://"+id;}
 public static String assetId(String ref){return ref!=null&&ref.startsWith("asset://")?ref.substring(8):ref;}
 public static long time(String t){ServerTime s=ServerTime.parse(t);return s==null?0:s.toDate().getTime();}
 public static User user(JSONObject o){User u=new User();u.username=nullable(o,"username");JSONObject settings=o.optJSONObject("settings");u.accountPrivate=o.optBoolean("account_private",settings!=null&&settings.optBoolean("account_private"));u.contentAllowed=o.optBoolean("content_allowed",true);u.setUid(o.optString("profile_id",o.optString("id")));u.setFullName(o.optString("display_name","Người dùng"));u.setAvatarUrl(asset(nullable(o,"avatar_asset_id")));u.setAvatarPreset(o.optString("avatar_preset","neutral"));u.setCoverUrl(asset(nullable(o,"cover_asset_id")));u.setBio(o.isNull("bio")?"":o.optString("bio",""));u.setLocation(nullable(o,"location"));u.setDateOfBirth(nullable(o,"birth_date"));u.setGender(nullable(o,"gender"));u.setProfileCompleted(o.optBoolean("onboarding_completed"));return u;}
public static Post post(JSONObject o){Post p=new Post();p.setPostId(o.optString("id"));p.setGroupId(nullable(o,"group_id"));p.setPostState(nullable(o,"state"));p.setAuthorUid(nullable(o,"author_id"));JSONObject a=o.optJSONObject("author");p.setUserName(a==null?"Người dùng":a.optString("display_name","Người dùng"));p.setUserAvatar(a==null?"":asset(nullable(a,"avatar_asset_id")));p.setUserAvatarPreset(a==null?"neutral":a.optString("avatar_preset","neutral"));p.setContent(o.optString("body",""));p.setVisibility(o.optString("audience","public"));p.setType(o.optString("kind").equals("share")?"share":"normal");p.setOriginalPostId(nullable(o,"original_post_id"));p.setMentions(o.optJSONArray("mentions"));p.setTags(o.optJSONArray("tags"));p.setLikesCount(o.optInt("reactions_count"));p.setCommentsCount(o.optInt("comments_count"));p.setSharesCount(o.optInt("shares_count"));p.setReaction(nullable(o,"my_reaction"));p.setSaved(o.optBoolean("is_saved",false));p.setReel(o.optBoolean("is_reel",false));p.setReelFollowing(o.optBoolean("is_following",false));p.setReelViewsCount(o.optInt("views_count",o.optInt("view_count")));p.setReelDurationMs(o.optInt("reel_duration_ms"));p.setReelCoverPositionMs(o.optInt("reel_cover_position_ms"));p.setReelCoverAssetId(nullable(o,"reel_cover_asset_id"));p.setMusicMetadata(o.optJSONObject("music_metadata"));p.version=o.optLong("version",1);p.serverCreatedAt=o.optString("created_at");p.setCreatedAt(time(p.serverCreatedAt));p.setUpdatedAt(time(o.optString("updated_at")));p.setTimeAgo(com.example.meetomxh.ui.PostTimestampFormatter.format(p.serverCreatedAt));List<String> assets=new ArrayList<>(),types=new ArrayList<>();JSONArray media=o.optJSONArray("media");if(media!=null)for(int i=0;i<media.length();i++){JSONObject item=media.optJSONObject(i);assets.add(asset(item.optString("asset_id")));types.add(item.optString("mime_type","image/*"));}p.setImageUrls(assets);p.setMediaTypes(types);if(!assets.isEmpty()){p.setPostImage(assets.get(0));p.setMediaType(types.get(0).startsWith("video/")?"video":"image");}return p;}
 public static ChatMessage message(JSONObject o){ChatMessage m=new ChatMessage();m.setMessageId(o.optString("id"));m.setSenderId(nullable(o,"sender_id"));m.seq=o.optLong("seq");m.version=o.optLong("version");m.setCreatedAt(ServerTime.parse(o.optString("created_at")));m.setEditedAt(ServerTime.parse(o.optString("edited_at")));m.setForwarded(o.optBoolean("forwarded",false));m.setRecalled(!o.optString("state").equals("sent"));m.setText(o.isNull("body")?"":o.optString("body"));String kind=o.optString("kind");m.setType("media".equals(kind)?"image":"voice".equals(kind)?"voice":"text");JSONObject shared=o.optJSONObject("shared_post");m.setSharedPost(shared==null?null:nullable(shared,"id"),o.optBoolean("shared_post_present"),o.optBoolean("shared_post_available"));m.setSharedPostVideoAssetId(sharedVideoAssetId(shared));if(shared!=null){JSONObject author=shared.optJSONObject("author");if(author!=null)m.setSharedAvatar(asset(nullable(author,"avatar_asset_id")),author.optString("avatar_preset","neutral"));m.setSharedContext(author==null?"Người dùng":author.optString("display_name","Người dùng"),shared.optString("body",""));JSONArray previews=shared.optJSONArray("media");if(previews!=null&&previews.length()>0){JSONObject first=previews.optJSONObject(0);m.setSharedPreview(asset(nullable(first,"asset_id")),first.optString("mime_type","image/*"));}}JSONObject story=o.optJSONObject("reply_story");String storyId=nullable(o,"reply_story_id");if(storyId!=null){m.setStoryContext(storyId,story==null?null:nullable(story,"caption"));m.setStoryAuthor(story==null?null:nullable(story,"author_id"));}JSONArray media=o.optJSONArray("media");if(media!=null&&media.length()>0){JSONObject first=media.optJSONObject(0);if(first!=null){String mime=first.optString("mime_type","image/*");if(first.has("asset_id"))m.setImageUrl(asset(first.optString("asset_id")));m.setMediaMimeType(mime);m.setVoiceDurationMs(first.optLong("duration_ms",0));if("media".equals(kind))m.setType(mime.startsWith("video/")?"video":"image");}}JSONObject reply=o.optJSONObject("reply");m.setReplyToMessageId(nullable(o,"reply_to_message_id"));if(reply!=null){m.setReplyToSeq(reply.optLong("seq"));m.setReplyToSenderId(nullable(reply,"sender_id"));if("recalled".equals(reply.optString("state")))m.setReplyPreview("Tin nhắn đã thu hồi");else if("voice".equals(reply.optString("kind")))m.setReplyPreview("Tin nhắn thoại");else if("media".equals(reply.optString("kind"))){JSONArray replyMedia=reply.optJSONArray("media");String mime=replyMedia==null||replyMedia.length()==0?"":replyMedia.optJSONObject(0).optString("mime_type","");m.setReplyPreview(mime.startsWith("video/")?"Video":"Ảnh");}else m.setReplyPreview(reply.isNull("body")?"Tin nhắn không còn hiển thị":reply.optString("body"));}else if(o.optBoolean("reply_reference_present"))m.setReplyPreview("Tin nhắn gốc không còn khả dụng");return m;}
 private static String sharedVideoAssetId(JSONObject shared){JSONArray media=shared==null?null:shared.optJSONArray("media");if(media==null)return null;for(int i=0;i<media.length();i++){JSONObject item=media.optJSONObject(i);if(item!=null&&item.optString("mime_type").startsWith("video/")&&!item.isNull("asset_id"))return item.optString("asset_id");}return null;}
 public static Chat chat(JSONObject o){Chat c=new Chat();c.themeId=o.optString("theme_id","meeto_pink");c.peerName=nullable(o,"peer_name");c.setChatId(o.optString("id"));c.setType(o.optString("kind"));c.title=nullable(o,"title");if(c.title==null||c.title.trim().isEmpty()||"null".equalsIgnoreCase(c.title))c.title="group".equals(c.getType())?"Nhóm chat":"Cuộc trò chuyện";c.archived=o.optBoolean("archived");c.avatar=asset(nullable(o,"avatar_asset_id"));c.ownerId=nullable(o,"owner_id");c.state=o.optString("state");c.role=o.optString("role");c.version=o.optLong("version");c.highWater=o.optLong("high_water");c.lastReadSeq=o.optLong("last_read_seq");c.lastDeliveredSeq=o.optLong("last_delivered_seq");c.unreadCount=o.optLong("unread_count");c.setCreatedAt(ServerTime.parse(o.optString("created_at")));c.setUpdatedAt(ServerTime.parse(o.optString("updated_at")));JSONObject last=o.optJSONObject("last_message");if(last!=null){ChatMessage m=message(last);c.setLastMessageId(m.getMessageId());c.setLastMessage(m.getDisplayText());c.setLastMessageType(m.getType());c.setLastMessageSenderId(m.getSenderId());c.setLastMessageAt(m.getCreatedAt());}return c;}
public static Comment comment(JSONObject o){if(o==null||o.isNull("body")||!"published".equals(o.optString("state","published")))return null;Comment c=new Comment();c.setCommentId(o.optString("id"));c.setPostId(o.optString("post_id"));c.setAuthorUid(nullable(o,"author_id"));c.setAuthorName(o.optString("author_name","Thành viên"));c.setAuthorAvatar(asset(nullable(o,"author_avatar_asset_id")));c.setAuthorAvatarPreset(o.optString("author_avatar_preset","neutral"));c.setContent(o.optString("body",""));c.mentions=o.optJSONArray("mentions")==null?new JSONArray():o.optJSONArray("mentions");c.serverCreatedAt=o.optString("created_at");c.setCreatedAt(time(c.serverCreatedAt));c.parentId=nullable(o,"parent_id");c.displayParentId=nullable(o,"display_parent_id");c.rootId=nullable(o,"root_id");c.depth=o.optInt("depth",0);c.displayDepth=o.optInt("display_depth",c.depth);c.replyCount=Math.max(0,o.optInt("reply_count",0));c.state=o.optString("state","published");c.version=o.optLong("version",1);c.reactionsCount=o.optInt("reactions_count");c.myReaction=nullable(o,"my_reaction");JSONObject preview=o.optJSONObject("preview_reply");if(preview!=null)c.previewReply=comment(preview);c.hasMoreReplies=c.replyCount>(c.previewReply==null?0:1);return c;}
}
